mapper.select:
select id, name, uri, method, create_user, create_time, update_user, update_time, deleted from router
name like concat('%',#{router.name},'%')
and uri=#{router.uri}
and method=#{router.method}
and deleted=0
order by create_time desc,update_time desc

select COUNT(id)
from router


        uri=#{router.uri}


        and method=#{router.method}

    and deleted=0
